// ============================================================
// 🔑 مفاتيح الـ API الاحتياطية (تدعم مفاتيح AIza من AI Studio ومفاتيح AQ. من Vertex AI!)
// ============================================================
const API_KEYS = [
  "PUT_BACKUP_API_KEY_1_HERE",
  "PUT_BACKUP_API_KEY_2_HERE",
  "PUT_BACKUP_API_KEY_3_HERE",
  "PUT_BACKUP_API_KEY_4_HERE",
  "PUT_BACKUP_API_KEY_5_HERE",
  "PUT_BACKUP_API_KEY_6_HERE"
];

const MODELS = [
  "gemini-2.5-flash",
  "gemini-2.5-flash-lite",
  "gemini-2.0-flash",
  "gemini-3.6-flash",
  "gemini-3.1-flash-lite"
];

const SYSTEM_PROMPT = `أنت 'نانو' (Nano)، الذكاء الاصطناعي المحلي الطائر من فريق Agentic Mind، متخصص في مساعدة طلاب تكنولوجيا المعلومات (IT) وإدارة الأعمال (Business).
أنت مزوّد بقاعدة معرفة من ملفات PDF الخاصة بمواد كلية الأعمال (إدارة 1 و2، اقتصاد جزئي وكلّي، مبادئ مالية، محاسبة 1 و2).
إذا وُجدت [معلومات مرجعية مستخرجة من ملفات PDF مواد الجامعة] مع السؤال، اعتمد عليها بدقة واذكر اسم المادة بوضوح.
أجب بلطف ووضوح واختصار بالعربية (أو الإنجليزية إذا خاطبك المستخدم بها).`;

let userMessage = "مرحبا";
try {
  userMessage = $('When chat message received').first().json.chatInput || userMessage;
} catch (e) {
  userMessage = $input.first().json.chatInput || userMessage;
}

const validKeys = API_KEYS.filter(k => k && !k.startsWith("PUT_BACKUP_API_KEY_"));

let replyText = null;
let usedKeyIndex = -1;
let usedModel = null;
let lastError = "لا توجد مفاتيح مضافة";

for (let i = 0; i < validKeys.length && !replyText; i++) {
  const apiKey = validKeys[i].trim();
  const isVertexKey = apiKey.startsWith("AQ.");

  for (let m = 0; m < MODELS.length && !replyText; m++) {
    const model = MODELS[m];
    const url = isVertexKey
      ? `https://aiplatform.googleapis.com/v1/publishers/google/models/${model}:generateContent?key=${apiKey}`
      : `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url,
        headers: { 'Content-Type': 'application/json' },
        body: {
          systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
          contents: [{ role: 'user', parts: [{ text: userMessage }] }],
          generationConfig: { temperature: 0.6, maxOutputTokens: 450 }
        },
        json: true,
        timeout: 15000
      });

      const candidate = res?.candidates?.[0]?.content?.parts?.[0]?.text;
      if (candidate) {
        replyText = candidate.trim();
        usedKeyIndex = i + 1;
        usedModel = model;
      }
    } catch (err) {
      lastError = `Key #${i + 1} (${model}): ${err.message || err}`;
      continue;
    }
  }
}

if (!replyText) {
  throw new Error("كل المفاتيح الستة فشلت — آخر خطأ: " + lastError);
}

return [{ json: { output: replyText, usedKeyIndex, usedModel } }];
